// Pojmi za igre: bio2 (glej README.md v tej mapi).
// Dodatni pojmi za biologijo (OŠ 8.–9. razred, gimnazija 1.–4. letnik): po en pojem za vsako temo
// učnega načrta, ki v bio.js še nima igre. Banke vprašanj: [stopnja, "vprašanje|pravilno|napačno|…" sl, isto en];
// "a~b~c" v odgovoru pomeni, da se ob vsakem vprašanju izbere ena možnost. Nekaj pojmov je računskih.

export const SUBJECT = "BIO";
export const AREAS = [];

// ---------- pomožne ----------
const R = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const shuffle = (a) => {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
};
const alt = (s) => pick(s.split("~"));
const C = [];
const def = (id, area, year, glyph, sl, en, gen) => C.push({ id, area, year, glyph, name: { sl, en }, gen });

// Naloga: 3–4 napačni (premešani), brez podvajanja in brez pravilnega.
function out(q, a, ws) {
  const seen = new Set([a]);
  const w = [];
  for (const s of shuffle(ws)) {
    if (s == null || s === "" || seen.has(s) || w.length >= 4) continue;
    seen.add(s);
    w.push(s);
  }
  return { q, a, w };
}
// Banka: stopnja 1 vzame vnose 1; stopnji 2 in 3 večinoma svoje, v 30 % z nižje stopnje.
function bank(items) {
  return (tier, ctx) => {
    let lv = tier;
    if (tier > 1 && Math.random() < 0.3) lv = tier - 1;
    let pool = items.filter((it) => it[0] === lv);
    if (!pool.length) pool = items.filter((it) => it[0] <= tier);
    const it = pick(pool);
    const [q, a, ...ws] = (ctx.lang === "sl" ? it[1] : it[2]).split("|");
    return out(q, alt(a), ws.map(alt));
  };
}
const defBank = (id, area, year, glyph, sl, en, items) => def(id, area, year, glyph, sl, en, bank(items));
// številski odgovor: napačni so števila (tipične napake), oblikovana s ctx.num; brez podvajanja
function numQ(ctx, q, a, ws, unit = "") {
  const f = (x) => ctx.num(Math.round(x * 1000) / 1000) + (unit ? " " + unit : "");
  const okw = ws.filter((x) => Number.isFinite(x) && x >= 0 && Math.abs(x - a) > 1e-9).map(f);
  const fill = [a + 1, a * 2, a / 2, a + 2, a * 10].filter((x) => Number.isFinite(x) && x > 0 && Math.abs(x - a) > 1e-9).map(f);
  return out(q, f(a), [...new Set(okw)].length >= 3 ? okw : [...okw, ...fill]);
}

