def("b2_design", "bi_eko", 9, "x→y", "Načrtovanje poskusa", "Planning an experiment", (t, ctx) => {
  const sl = ctx.lang === "sl";
  if (t === 3 && Math.random() < 0.7) return DESIGN(3, ctx);
  const [title, ind, dep, ...cs] = pick(EXPS)[sl ? 0 : 1];
  const askDep = t === 2 ? Math.random() < 0.7 : Math.random() < 0.2;
  if (askDep) return out(`${title}: ${sl ? "odvisna spremenljivka?" : "dependent variable?"}`, dep, [ind, ...cs]);
  return out(`${title}: ${sl ? "neodvisna spremenljivka?" : "independent variable?"}`, ind, [dep, ...cs]);
});

