def("b2_membrane", "bi_cel", 10, "⇄", "Biotska membrana in transport", "Membranes and transport", (t, ctx) => {
  if (t === 3 && Math.random() < 0.4) {
    const sl = ctx.lang === "sl";
    const a = pick([1, 2, 3, 6]);
    const q = sl ? `Kocka s stranico ${a} µm: razmerje P/V?` : `Cube of side ${a} µm: surface-to-volume ratio?`;
    return numQ(ctx, q, 6 / a, [6 * a * a, a * a * a, a / 6, 12 / a, 3 / a], "µm⁻¹");
  }
  return MEMB(t, ctx);
});

