def("b2_pop", "bi_eko", 12, "N(t)", "Populacije", "Populations", (tier, ctx) => {
  const sl = ctx.lang === "sl";
  if (tier === 1 && Math.random() < 0.4) {
    const A = pick([2, 4, 5, 8, 10]);
    const d = pick([3, 4, 6, 12, 15, 25]);
    const N = A * d;
    return numQ(ctx, sl ? `${N} srn na ${A} ha: gostota (na ha)?` : `${N} deer on ${A} ha: density (per ha)?`, d, [N * A, N - A, N + A, d * 2, d + A]);
  }
  if (tier === 2 && Math.random() < 0.45) {
    const B = R(20, 60), D = R(10, 50), I = R(2, 15);
    const E = I === 15 ? 3 : (I + R(1, 9)) % 16 || 2;
    const c = B - D + I - E;
    const fmt = (x) => (x > 0 ? "+" : "") + ctx.num(x);
    const ws = [B - D, B - D - I + E, -c, B + D + I + E].filter((x) => x !== c).map(fmt);
    return out(sl ? `Rojeni: ${B}, umrli: ${D}, prišli: ${I}, odšli: ${E}. Sprememba?` : `Born ${B}, died ${D}, in ${I}, out ${E}: net change?`, fmt(c), ws);
  }
  if (tier === 3 && Math.random() < 0.6) {
    const M = pick([20, 30, 40, 50, 60]);
    const R2 = pick([2, 4, 5, 10]);
    const k = pick([3, 4, 5, 6, 8]);
    const C2 = R2 * k;
    const N = (M * C2) / R2;
    return numQ(ctx, sl ? `Označenih ${M}; ulov ${C2}, od tega ${R2} ${R2 === 2 ? "označena" : R2 < 5 ? "označeni" : "označenih"}. Ocena N?` : `${M} marked; catch ${C2}, ${R2} marked. Estimate N?`, N, [M + C2, M * C2, Math.round((M * R2) / C2), N / 2, N * 2]);
  }
  return popBank(tier, ctx);
});

