def("b2_popgen", "bi_ded", 13, "p+q", "Populacijska genetika", "Population genetics", (tier, ctx) => {
  const sl = ctx.lang === "sl";
  const k = R(1, 9); // q = k/10
  const q = k / 10, p = (10 - k) / 10;
  const two = (x) => Math.round(x * 100) / 100;
  if (tier === 1 && Math.random() < 0.5) {
    return numQ(ctx, sl ? `Pogostost alela a je ${ctx.num(q)}. Pogostost A?` : `Frequency of allele a is ${ctx.num(q)}. Frequency of A?`, p, [q, two(p * p), two(q * q), 1 + q]);
  }
  if (tier === 2 && Math.random() < 0.5) {
    if (Math.random() < 0.5)
      return numQ(ctx, sl ? `Ravnovesje, q = ${ctx.num(q)}. Delež genotipa aa?` : `Equilibrium, q = ${ctx.num(q)}. Frequency of aa?`, two(q * q), [q, two(2 * q), two(2 * p * q), two(p * p), two(1 - q * q)]);
    return numQ(ctx, sl ? `Ravnovesje, p = ${ctx.num(p)}. Delež genotipa AA?` : `Equilibrium, p = ${ctx.num(p)}. Frequency of AA?`, two(p * p), [p, two(2 * p), two(2 * p * q), two(q * q), two(1 - p * p)]);
  }
  if (tier === 3 && Math.random() < 0.6) {
    const aa = k * k; // v %
    const het = 2 * k * (10 - k);
    const AA = (10 - k) * (10 - k);
    return numQ(ctx, sl ? `Ravnovesje: ${ctx.num(aa)} % je aa. Delež Aa (v %)?` : `Equilibrium: ${ctx.num(aa)}% are aa. Percent Aa?`, het, [AA, k * 10, 2 * aa, 100 - aa, 50, het + 10, het / 2].filter((x) => x <= 100), "");
  }
  return pgenBank(tier, ctx);
});

